INSERT INTO tb_point_balance(fmly_cd, total_point)
	VALUES (#{fmlyCd} ,
		round((select sum(earn_point) from tb_point_earn where fmly_cd=#{fmlyCd})
			- (select sum(using_point) from tb_point_using where fmly_cd=#{fmlyCd}),1)
			);

INSERT INTO
	point_hist
		(sale_id
		, cstmr_cd
		, fmly_cd
		, point
		, shop_num
		, date_time
		, point_status)
	VALUES
		(#{saleId}
		,#{cstmrCd}
		,#{fmlyCd}
		,#{point}
		,#{shopNum}
		,#{dateTime}
		,#{pointStatus});

