UPDATE
	cstmr
SET
	fmly_cd = #{fmlyCd}
WHERE
	cstmr_cd = #{cstmrCd}

mapper.select:
    	SELECT
			count(*)
		FROM
			point_hist
		WHERE
			sale_id = #{saleId}
			and fmly_cd = #{fmlyCd}
			and point_status=#{pointStatus}

SELECT
	point_id
FROM
	point_hist
WHERE
	sale_id = #{saleId}
	and fmly_cd = #{fmlyCd}
	and point_status=#{pointStatus}
order by point_id desc limit 1;

